#!/usr/bin/env bash
# jhh3-mem — lib/uninstall.sh
# Complete, provable removal. SPEC §10.2, §10.4.
#
# The tool this replaces left detached daemons and caches across 6+ paths and
# ~1.5 GB after its own uninstall. The corrective is not a longer rm list — it
# is that `jm_paths_manifest` is generated by the same code that creates the
# paths, so it cannot drift, and that every claim this script makes is printed
# as a command the user can re-run themselves.
#
# Without --purge this is a DRY RUN. It is the default because deleting a
# memory store must be a deliberate act.
#
# shellcheck shell=bash

if [ -z "${JM_UNINSTALL_SOURCED:-}" ]; then
  JM_UNINSTALL_SOURCED=1
  _jm_uni_src="${BASH_SOURCE[0]}"
  case "$_jm_uni_src" in */*) _jm_uni_dir="${_jm_uni_src%/*}" ;; *) _jm_uni_dir="." ;; esac
  # shellcheck source=./db.sh
  . "$_jm_uni_dir/db.sh"
  unset _jm_uni_src _jm_uni_dir
fi

# _jm_uninstall_safe_target — refuse to rm -rf anything that is not plainly a
# jhh3-mem store. rc 0 safe · 1 refuse.
_jm_uninstall_safe_target() {
  local d="$JM_HOME"
  case "$d" in
    /*) : ;;
    *) return 1 ;;
  esac
  [ "$d" = '/' ] && return 1
  [ "$d" = "$HOME" ] && return 1
  [ "$d" = "${HOME%/}/" ] && return 1
  # at least two path components below root
  case "${d#/}" in
    */*) : ;;
    *) return 1 ;;
  esac
  # A mis-set JHH3_MEM_HOME must not be able to delete a real tree: the target
  # has to look like OUR store — it holds one of our artifacts, or it is empty.
  if [ -e "$JM_DB" ] || [ -e "$JM_LOG" ] || [ -e "$JM_LOCK" ] || [ -d "$JM_BACKUPS" ]; then
    return 0
  fi
  if [ -z "$(ls -A -- "$d" 2>/dev/null)" ]; then
    return 0
  fi
  return 1
}

# _jm_uninstall_stats — "bytes|entries|repos|origins" for the store, best effort.
_jm_uninstall_stats() {
  local bytes=0 entries='-' repos='-' p
  while IFS= read -r p; do
    [ -f "$p" ] || continue
    bytes=$((bytes + $(_jm_file_size "$p")))
  done < <(jm_paths_manifest)
  if [ -d "$JM_BACKUPS" ]; then
    while IFS= read -r p; do
      [ -f "$p" ] || continue
      bytes=$((bytes + $(_jm_file_size "$p")))
    done < <(find "$JM_BACKUPS" -type f 2>/dev/null || true)
  fi
  if jm_have sqlite3 && [ -s "$JM_DB" ]; then
    entries="$(jm_db_read 'SELECT count(*) FROM entries;' 2>/dev/null)" || entries='-'
    repos="$(jm_db_read 'SELECT count(DISTINCT repo_key) FROM entries;' 2>/dev/null)" || repos='-'
  fi
  printf '%s|%s|%s\n' "$bytes" "${entries:--}" "${repos:--}"
}

# jm_uninstall_export FILE — NDJSON of every entry. rc 0 · 1 failed · 2 nothing.
jm_uninstall_export() {
  local out="${1:-}"
  [ -n "$out" ] || return 2
  # User-supplied (`export --out`): keep a leading '-' from reading as an option,
  # since chmod below takes no `--` (BSD chmod treats `--` as a file operand).
  case "$out" in -*) out="./$out" ;; esac
  jm_have sqlite3 || return 1
  [ -s "$JM_DB" ] || return 2
  jm_db_read "SELECT json_object(
      'id', id, 'uid', uid, 'origin', origin, 'producer', producer,
      'repo_key', repo_key, 'worktree', worktree, 'branch', branch,
      'repo_path', repo_path, 'kind', kind, 'ts', ts, 'started_at', started_at,
      'title', title, 'request', request, 'outcome', outcome,
      'learned', learned, 'decided', decided, 'next_steps', next_steps,
      'facts', facts, 'concepts', concepts, 'files_touched', files_touched,
      'commands', commands, 'capture_mode', capture_mode, 'end_reason', end_reason,
      'turns', turns, 'redactions', redactions, 'durability', durability,
      'dedup_key', dedup_key, 'n_mod', n_mod, 'n_read', n_read,
      'ephemeral', ephemeral, 'injectable', injectable, 'superseded', superseded)
    FROM entries ORDER BY id;" >"$out" 2>/dev/null || return 1
  [ -s "$out" ] || { rm -f -- "$out"; return 2; }
  chmod 0600 "$out" 2>/dev/null || true
  return 0
}

# jm_uninstall_verify — the §10.4 verification block, with each claim's command
# printed next to its live result so the user can re-run any of them.
jm_uninstall_verify() {
  local n hit hitp
  printf 'verification (re-run any of these yourself)\n'
  printf '  %-46s -> %s\n' "test -e $JM_HOME" \
    "$([ -e "$JM_HOME" ] && printf 'PRESENT' || printf 'absent')"

  if jm_have find; then
    n="$(find "$HOME" -maxdepth 4 -name 'jhh3-mem*' 2>/dev/null | wc -l | tr -d ' ')"
    printf '  %-46s -> %s\n' "find \"\$HOME\" -maxdepth 4 -name 'jhh3-mem*'" \
      "$([ "$n" = '0' ] && printf '(no matches)' || printf '%s match(es)' "$n")"
    # Anything left under ~/.claude is Claude Code's own area (the installed
    # plugin code, a marketplace clone, a session transcript that happens to
    # mention us). jhh3-mem stores NOTHING there — so list every hit by name
    # rather than asserting a zero the user cannot check.
    printf '  %-46s -> ' "find \"\$HOME/.claude\" -name '*jhh3-mem*'"
    n=0
    while IFS= read -r hit; do
      [ -n "$hit" ] || continue
      n=$((n + 1))
      [ "$n" -eq 1 ] && printf 'not jhh3-mem data:\n'
      [ "$n" -le 5 ] && printf '      %s\n' "$hit"
    done < <(find "$HOME/.claude" -name '*jhh3-mem*' 2>/dev/null || true)
    [ "$n" -eq 0 ] && printf '(no matches)\n'
    [ "$n" -gt 5 ] && printf '      ... and %s more (all Claude Code paths)\n' "$((n - 5))"
  else
    printf '  %-46s -> [skip] find is not installed\n' "find \"\$HOME\" -maxdepth 4 -name 'jhh3-mem*'"
  fi

  if jm_have pgrep; then
    # jm_probe_processes (lib/common.sh) is shared with `doctor`: one probe,
    # one definition of "is there a jhh3-mem process", and it never prints a
    # row it cannot name.
    n=0
    printf '  %-46s -> ' 'pgrep -fa jhh3-mem'
    while IFS= read -r hitp; do
      [ -n "$hitp" ] || continue
      n=$((n + 1))
      [ "$n" -eq 1 ] && printf 'no jhh3-mem daemon; other processes merely naming it:\n'
      [ "$n" -le 5 ] && printf '      %s\n' "$hitp"
    done < <(jm_probe_processes)
    [ "$n" -eq 0 ] && printf '(none)   [expected: this plugin has no daemon]\n'
  else
    printf '  %-46s -> [skip] pgrep is not installed\n' 'pgrep -fa jhh3-mem'
  fi

  # Staging artifacts under $TMPDIR. They live for milliseconds in a normal run,
  # but a SIGKILL outlives the cleanup, and until this line existed neither the
  # inventory nor the purge could see them.
  local tn=0 g hit
  while IFS= read -r g; do
    # shellcheck disable=SC2086  # $g is our own glob, deliberately unquoted
    for hit in $g; do
      [ -e "$hit" ] && tn=$((tn + 1))
    done
  done < <(jm_paths_transient)
  printf '  %-46s -> %s\n' "ls -d \"\$TMPDIR\"/jhh3-mem.*" \
    "$([ "$tn" -eq 0 ] && printf '(none)' || printf '%s staging artifact(s) — removed by --purge' "$tn")"

  if jm_have ss; then
    n="$(ss -ltnp 2>/dev/null | grep -c 'jhh3-mem' || true)"
    printf '  %-46s -> %s\n' 'ss -ltnp | grep jhh3-mem' \
      "$([ "$n" = '0' ] && printf '(none)   [expected: this plugin opens no port]' || printf '%s socket(s)' "$n")"
  else
    printf '  %-46s -> [skip] ss is not installed; run it yourself\n' 'ss -ltnp | grep jhh3-mem'
  fi
  return 0
}

# jm_uninstall_run PURGE YES NO_BACKUP
# stdout: the removal report (§10.4).
# rc 0 removed (or dry run completed) · 1 refused · 2 nothing to remove.
jm_uninstall_run() {
  local purge="${1:-0}" yes="${2:-0}" no_backup="${3:-0}"
  local stats bytes entries repos p export_file='' legacy=''

  # Read provenance BEFORE anything is deleted.
  legacy="$( (jm_db_read "SELECT v FROM meta WHERE k='legacy_source';" 2>/dev/null) || true)"

  # Strip the nightly job first, whatever else happens below: a crontab line
  # pointing at a CLI we are about to delete would fire nightly into the void.
  if [ "$purge" = '1' ] && [ "$yes" = '1' ]; then
    # shellcheck source=schedule.sh
    [ -r "${JM_LIB_DIR:-}/schedule.sh" ] && . "${JM_LIB_DIR}/schedule.sh" 2>/dev/null
    command -v jm_schedule_remove >/dev/null 2>&1 && jm_schedule_remove
    command -v jm_shim_remove >/dev/null 2>&1 && jm_shim_remove
  fi

  if [ ! -e "$JM_HOME" ]; then
    printf 'nothing to remove\n'
    printf '  %s does not exist\n' "$JM_HOME"
    printf '\n'
    jm_uninstall_verify
    return 2
  fi

  stats="$(_jm_uninstall_stats)"
  bytes="${stats%%|*}"; stats="${stats#*|}"
  entries="${stats%%|*}"; repos="${stats#*|}"

  # ── dry run ──────────────────────────────────────────────────────────────
  if [ "$purge" != '1' ]; then
    printf 'DRY RUN — nothing was removed. Re-run with --purge --yes to delete.\n'
    printf 'would remove\n'
    printf '  %-52s %s, %s entries, %s repos\n' "$JM_HOME/" "$(jm_human_bytes "$bytes")" "$entries" "$repos"
    printf 'path inventory (everything jhh3-mem ever creates)\n'
    while IFS=$'\t' read -r p kind mode note; do
      printf '  %-52s %-5s %-5s %s%s\n' "$p" "$kind" "$mode" "$note" \
        "$([ -e "${p%/}" ] && printf ' [exists]' || printf ' [absent]')"
    done < <(jm_paths_manifest_annotated)
    printf '\n'
    jm_uninstall_verify
    _jm_uninstall_left_alone '' "$legacy"
    printf 'next\n'
    printf '  jhh3-mem uninstall --purge --yes\n'
    return 0
  fi

  # ── refusals ─────────────────────────────────────────────────────────────
  local has_rows=0
  case "$entries" in '' | '-' | 0) has_rows=0 ;; *) has_rows=1 ;; esac

  if [ "$has_rows" = '1' ] && [ "$yes" != '1' ]; then
    printf 'refused: %s holds %s entries across %s repos.\n' "$JM_HOME" "$entries" "$repos" >&2
    printf '         Re-run with --yes to confirm deletion.\n' >&2
    jm_log uninstall noop 'reason=refused_no_yes'
    return 1
  fi

  # Because bin/ is on the agent's PATH, a non-interactive purge additionally
  # requires the caller to name the exact directory it is deleting.
  if [ ! -t 0 ] && [ "${JHH3_MEM_CONFIRM:-}" != "$JM_HOME" ]; then
    printf 'refused: non-interactive --purge requires JHH3_MEM_CONFIRM=%s in the environment.\n' \
      "$JM_HOME" >&2
    jm_log uninstall noop 'reason=refused_no_confirm'
    return 1
  fi

  if ! _jm_uninstall_safe_target; then
    printf 'refused: %s does not look like a jhh3-mem store; not deleting it.\n' "$JM_HOME" >&2
    jm_log uninstall error 'reason=unsafe_target'
    return 1
  fi

  # ── final export, into the CWD — never into the directory being deleted ──
  if [ "$no_backup" != '1' ] && [ "$has_rows" = '1' ]; then
    export_file="$PWD/jhh3-mem-final-export-$(date +%Y-%m-%d-%H%M%S).jsonl"
    if ! jm_uninstall_export "$export_file"; then
      printf 'refused: the final export to %s failed; nothing removed.\n' "$export_file" >&2
      printf '         Re-run with --no-backup if you truly want no export.\n' >&2
      jm_log uninstall error 'reason=export_failed'
      return 1
    fi
  fi

  # ── remove ───────────────────────────────────────────────────────────────
  rm -rf -- "$JM_HOME" || {
    printf 'refused: could not remove %s\n' "$JM_HOME" >&2
    jm_log uninstall error 'reason=rm_failed'
    return 1
  }

  # Staging artifacts under $TMPDIR are part of "everything it ever created".
  # A normal run deletes its own; this sweeps whatever a SIGKILL orphaned.
  local g hit tremoved=0
  while IFS= read -r g; do
    # shellcheck disable=SC2086  # $g is our own glob, deliberately unquoted
    for hit in $g; do
      [ -e "$hit" ] || continue
      rm -rf -- "$hit" 2>/dev/null && tremoved=$((tremoved + 1))
    done
  done < <(jm_paths_transient)

  printf 'removed\n'
  printf '  %-52s %s, %s entries, %s repos\n' "$JM_HOME/" "$(jm_human_bytes "$bytes")" "$entries" "$repos"
  [ "$tremoved" -gt 0 ] && \
    printf '  %-52s %s staging artifact(s)\n' "${TMPDIR:-/tmp}/jhh3-mem.*" "$tremoved"
  printf '\n'
  jm_uninstall_verify
  _jm_uninstall_left_alone "$export_file" "$legacy"
  printf 'next\n'
  printf '  /plugin uninstall jhh3-mem@acme-plugins\n'
  return 0
}

# _jm_uninstall_left_alone [EXPORT_FILE] — everything adjacent that this tool
# did NOT create and therefore will not claim or delete.
_jm_uninstall_left_alone() {
  local export_file="${1:-}" legacy="${2:-}"
  printf 'left alone (not created by jhh3-mem)\n'
  [ -n "$legacy" ] || legacy="$HOME/mem-archive/claude-mem.db"
  if [ -e "$legacy" ]; then
    printf '  %-52s legacy archive — delete manually if you want it gone\n' "$legacy"
  fi
  [ -n "$export_file" ] && [ -e "$export_file" ] \
    && printf '  %-52s your export\n' "$export_file"
  # The harness-managed plugin-data dir is never referenced by this plugin (see
  # lib/common.sh, T-INV-2). If Claude Code created it anyway, name it here — do
  # not claim it and do not delete it.
  local pd="$HOME/.claude/plugins/data/jhh3-mem"
  [ -e "$pd" ] && printf '  %-52s created by Claude Code, not by jhh3-mem\n' "$pd"
  return 0
}

# ── CLI ─────────────────────────────────────────────────────────────────────

_jm_uninstall_usage() {
  cat <<'USAGE'
usage: jhh3-mem uninstall [--purge] [--yes] [--no-backup]

  (no flags)     DRY RUN: print the full path inventory and the verification
                 commands. Nothing is removed.
  --purge        actually delete the store directory
  --yes          confirm deletion when the store holds entries
  --no-backup    skip the ./jhh3-mem-final-export-<ts>.jsonl written into CWD

  A non-interactive --purge additionally requires JHH3_MEM_CONFIRM to equal the
  store directory, because bin/ is on the agent's PATH.
USAGE
}

jm_uninstall_main() {
  local purge=0 yes=0 no_backup=0
  while [ $# -gt 0 ]; do
    case "$1" in
      --purge) purge=1; shift ;;
      --yes | -y) yes=1; shift ;;
      --no-backup) no_backup=1; shift ;;
      -h | --help) _jm_uninstall_usage; return 0 ;;
      *) printf 'uninstall: unknown argument: %s\n' "$1" >&2; _jm_uninstall_usage >&2; return 2 ;;
    esac
  done
  jm_uninstall_run "$purge" "$yes" "$no_backup"
}

if [ "${BASH_SOURCE[0]}" = "${0}" ]; then
  set -uo pipefail
  jm_uninstall_main "$@"
fi
